{
  "steps": [
    {
      "id": 1,
      "claim": "Total loans taken during college = 4 years × $50,000 per year = $200,000",
      "evidence": "Problem states Jim receives $50,000 in loans each year for a 4‑year program.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Lost earnings while in school = 4 years × $25,000 per year = $100,000",
      "evidence": "If Jim had not attended college he would have earned $25k per year.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Total amount to recover (deficit) = loans + lost earnings = $200,000 + $100,000 = $300,000",
      "evidence": "Add the amounts from steps 1 and 2.",
      "weight": 0.15,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Post‑college salary = 3 × $25,000 = $75,000 per year",
      "evidence": "Degree triples his pre‑college income of $25,000.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "Incremental earnings per year after college = $75,000 – $25,000 = $50,000",
      "evidence": "Difference between new salary and the salary he would have earned without college.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Years required to recover the $300,000 deficit = $300,000 ÷ $50,000 per year = 6 years",
      "evidence": "Divide total deficit (step 3) by incremental earnings per year (step 5).",
      "weight": 0.20,
      "depends_on": [3, 5]
    }
  ],
  "answer": "6",
  "confidence": 0.97,
  "considered": [
    {
      "answer": "4",
      "reason_rejected": "Uses total post‑college salary ($75,000) instead of the net increase; the $25,000 baseline is already accounted for in the lost‑wage component."
    },
    {
      "answer": "12",
      "reason_rejected": "Adds the 4 years of school to the repayment period, but the question asks only for the post‑college time needed to earn the equivalent amount."
    }
  ]
}
